const { test } = require("node:test");
const assert = require("node:assert");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { loadConfig } = require("./config-loader.js");

function writeTempJson(data) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "config-loader-"));
  const filePath = path.join(dir, "config.json");
  fs.writeFileSync(filePath, JSON.stringify(data));
  return filePath;
}

test("returns defaults when the file is missing", () => {
  const missingPath = path.join(os.tmpdir(), "config-loader-missing-does-not-exist.json");
  const defaults = { host: "localhost", port: 8080 };
  const result = loadConfig(missingPath, defaults);
  assert.deepStrictEqual(result, { host: "localhost", port: 8080 });
  // Merged object must be a copy, not the defaults object itself
  assert.notStrictEqual(result, defaults);
});

test("merges defaults with user values, defaults win conflicts", () => {
  const filePath = writeTempJson({ port: 3000, debug: true });
  const result = loadConfig(filePath, { host: "localhost", port: 8080 });
  assert.deepStrictEqual(result, { host: "localhost", port: 8080, debug: true });
});

test("defaults overwrite user values when they conflict", () => {
  const filePath = writeTempJson({ host: "example.com" });
  const result = loadConfig(filePath, { host: "localhost" });
  assert.deepStrictEqual(result, { host: "localhost" });
});

test("returns defaults when user config is empty", () => {
  const filePath = writeTempJson({});
  const result = loadConfig(filePath, { host: "localhost", port: 8080 });
  assert.deepStrictEqual(result, { host: "localhost", port: 8080 });
});

test("user config adds keys not present in defaults", () => {
  const filePath = writeTempJson({ debug: true });
  const result = loadConfig(filePath, { host: "localhost" });
  assert.deepStrictEqual(result, { host: "localhost", debug: true });
});

test("nested objects are replaced by the defaults object", () => {
  const filePath = writeTempJson({ db: { user: "admin" } });
  const result = loadConfig(filePath, { db: { user: "guest", host: "db.local" } });
  assert.deepStrictEqual(result, { db: { user: "guest", host: "db.local" } });
});

test("default value overrides user null", () => {
  const filePath = writeTempJson({ host: null });
  const result = loadConfig(filePath, { host: "localhost" });
  assert.deepStrictEqual(result, { host: "localhost" });
});
